function BattleStatisticPopupDialog:Awake()
    local argument = self.controller.Argument.parameters
    if argument and argument.data then
        self.dataByServer = argument.data
        local data = checkTable(self.dataByServer)
        -- print("StatisticData:" .. table.dump(data))
        for i, v in pairs(data) do
            -- print("->>preData:", table.dump(checkTable(v)))
        end
    end
    self.questType = BattleEndMgr and BattleEndMgr.questType or nil
    -- 可以手动设置关卡类型
    if not IsNull(argument.questType) then
        self.questType = argument.questType
    end
    -- self.questType = -200
    self.isInBattle = not IsNull(BattleEndMgr)

    -- 切换队伍的按钮默认关闭
    -- KTool.SetActive(self.PageGroup.gameObject, false)

    ---@type SuperScrollView.LoopListView2
    self.LoopListView = KTool.GetComponent(self.RT_LoopListView.gameObject, typeof(LoopListView2))

    self.teamStatisticInfo = {}
    self.infoNodeList = {}
    self.nullNodeList = {}
    self.teamId = self.isInBattle and checkTable(QuestConfMgr:GetInstance():GetQuestVoById(BattleEndMgr.questId)).petLineup or nil
    self.cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
    self.otherPlayerId = 0
end

