function BattleStatisticPopupDialog:InitLayoutDifference()
    local listViewRoot = self.RT_ListViewRoot.parent.parent
    if AnnihilationUtils.QuestTypeIsAnnihilation(self.questType) then
        listViewRoot.anchoredPosition = Vector3.New(0, -135, 0)
        listViewRoot.sizeDelta = Vector2.New(1373.2, 671.04)
        self.RT_TitleList.anchoredPosition = Vector3.New(0, 243, 0)
        KTool.SetParent(self.RT_TotalDamageNode.gameObject, self.RT_TotalDamageAnchorDown.gameObject)
        KTool.SetActive(self.RT_TabToggleGroup.gameObject, true)
        self:InitTabToggle(1, 2, {localize("我的数据"), localize("队友数据")})
    elseif self.questType == Constants.IDType.QuestLadderStruggle
    or self.questType == Constants.IDType.QuestChaoticRecall then
        listViewRoot.anchoredPosition = Vector3.New(0, -35, 0)
        listViewRoot.sizeDelta = Vector2.New(1373.2, 480)
        self.RT_TitleList.anchoredPosition = Vector3.New(0, 243, 0)
        KTool.SetParent(self.RT_TotalDamageNode.gameObject, self.RT_TotalDamageAnchorDown.gameObject)
        KTool.SetActive(self.RT_TabToggleGroup.gameObject, true)
        self:InitTabToggle(1, table.count(self.dataByServer))
    else
        listViewRoot.anchoredPosition = Vector3.New(0, -100, 0)
        listViewRoot.sizeDelta = Vector2.New(1373.2, 718)
        self.RT_TitleList.anchoredPosition = Vector3.New(0, 291.4, 0)
        KTool.SetParent(self.RT_TotalDamageNode.gameObject, self.RT_TotalDamageAnchorUp.gameObject)
        KTool.SetActive(self.RT_TabToggleGroup.gameObject, false)
    end
end

--- 把服务器数据格式转换成页面需要的数据格式
function BattleStatisticPopupDialog:ConvertTeamData()
    local statisticData = self.dataByServer
    -- print("[统计] ConvertTeamData o", table.dump(statisticData, nil, 8))

    if self.questType == Constants.IDType.QuestLadderStruggle then
        self.teamStatisticInfo = self:ConvertLadderStruggleTeamData(statisticData)
    elseif self.questType == Constants.IDType.QuestChaoticRecall then
        -- 一个team是一个label的数据
        self.teamStatisticInfo[1] = {}
        for i, teamData in pairs(statisticData) do
            local teamTotalData = self:ConvertTeamToLabelData(teamData)
            table.insert(self.teamStatisticInfo[1], teamTotalData)
        end
    else
        -- 一个team是一个page的数据
        for i, teamData in pairs(statisticData) do
            local teamTotalData
            if AnnihilationUtils.QuestTypeIsAnnihilation(self.questType) then
                teamTotalData = self:ConvertAnnihilationTeamData(teamData)
            else
                teamTotalData = self:ConvertNormalTeamData(teamData)
            end
            table.insert(self.teamStatisticInfo, teamTotalData)
        end
    end
    -- print("[统计] ConvertTeamData d", table.dump(self.teamStatisticInfo, nil, 8))
end

--- 把team数据转换成一个label的数据
---@param teamData any
function BattleStatisticPopupDialog:ConvertTeamToLabelData(teamData)
    local everyRoleData = {}     -- 每个人自己的数据
    local totalBear = 0
    local totalSkillCard = 0
    local totalDamage = 0
    local totalCure = 0
    for battleId, memberData in pairs(teamData) do
        memberData.index = checkInt(battleId)
        table.insert(everyRoleData, memberData)
        totalBear = totalBear + math.abs(memberData.bear)
        totalSkillCard = totalSkillCard + math.abs(memberData.skillCard)
        totalDamage = totalDamage + math.abs(memberData.damage)
        totalCure = totalCure + math.abs(memberData.cure)
    end
    -- -- 默认使用playerId1
    -- local playerId = BattleInfo.myPlayerId
    local teamTotalData = {
        roleData = everyRoleData,   -- 每个人自己的数据
        bear = totalBear,
        skillCard = totalSkillCard,
        damage = totalDamage,
        cure = totalCure,
    }
    -- 给角色排个序
    self:SortRoleDataByIndex(teamTotalData.roleData)

    return teamTotalData
end

--- 一般的构造数据(把一个team转换成一个page的数据)
---@param teamData any
function BattleStatisticPopupDialog:ConvertNormalTeamData(teamData)
    local everyRoleData = {}     -- 每个人自己的数据
    local totalBear = 0
    local totalSkillCard = 0
    local totalDamage = 0
    local totalCure = 0
    for battleId, memberData in pairs(teamData) do
        memberData.index = checkInt(battleId)
        table.insert(everyRoleData, memberData)
        totalBear = totalBear + math.abs(memberData.bear)
        totalSkillCard = totalSkillCard + math.abs(memberData.skillCard)
        totalDamage = totalDamage + math.abs(memberData.damage)
        totalCure = totalCure + math.abs(memberData.cure)
    end
    -- -- 默认使用playerId1
    -- local playerId = BattleInfo.myPlayerId
    local lableId = 1
    local teamTotalData = {
        [lableId] = {
            roleData = everyRoleData,   -- 每个人自己的数据
            bear = totalBear,
            skillCard = totalSkillCard,
            damage = totalDamage,
            cure = totalCure,
        }
    }
    -- 给角色排个序
    self:SortRoleDataByIndex(teamTotalData[lableId].roleData)

    return teamTotalData
end

--- 歼灭战构造数据
---@param teamData any
function BattleStatisticPopupDialog:ConvertAnnihilationTeamData(teamData)
    -- 组队战的时候，我方和友方的统计信息都在一个team里面，按playerId给他区分开
    local totalBear = 0
    local totalSkillCard = 0
    local totalDamage = 0
    local totalCure = 0
    local pageData = {}
    for battleId, memberData in pairs(teamData) do
        local playerId = memberData.playerId

        -- -- 现在一共就两个玩家，先这样写死
        -- if not UIBattlingTools.IsMyPlayerId(playerId) then
        --     self.otherPlayerId = playerId
        -- end

        local lableId = UIBattlingTools.IsMyPlayerId(playerId) and 1 or 2

        local labelData = pageData[lableId]
        if isNull(labelData) then
            labelData = {
                roleData = {},
                bear = 0,
                skillCard = 0,
                damage = 0,
                cure = 0,
            }
            pageData[lableId] = labelData
        end
        memberData.index = checkInt(battleId)  -- 战场id
        table.insert(labelData.roleData, memberData)
        labelData.bear = labelData.bear + math.abs(memberData.bear)
        labelData.skillCard = labelData.skillCard + math.abs(memberData.skillCard)
        labelData.damage = labelData.damage + math.abs(memberData.damage)
        labelData.cure = labelData.cure + math.abs(memberData.cure)
    end
    -- 给角色排序
    for lableId, lableData in pairs(pageData) do
        self:SortRoleDataByIndex(lableData.roleData)
    end

    return pageData
end

--- 大乱斗构造数据
---@param teamData any
function BattleStatisticPopupDialog:ConvertLadderStruggleTeamData(statisticData)
    local teamTotalData = {}
    for labelId, teamData in pairs(statisticData) do
        local everyRoleData = {}     -- 每个人自己的数据
        local totalBear = 0
        local totalSkillCard = 0
        local totalDamage = 0
        local totalCure = 0
        for battleId, memberData in pairs(teamData) do
            memberData.index = checkInt(battleId)
            table.insert(everyRoleData, memberData)
            totalBear = totalBear + math.abs(memberData.bear)
            totalSkillCard = totalSkillCard + math.abs(memberData.skillCard)
            totalDamage = totalDamage + math.abs(memberData.damage)
            totalCure = totalCure + math.abs(memberData.cure)
        end
        
        teamTotalData[labelId] = {
            roleData = everyRoleData,   -- 每个人自己的数据
            bear = totalBear,
            skillCard = totalSkillCard,
            damage = totalDamage,
            cure = totalCure,
        }
        -- 给角色排个序
        self:SortRoleDataByIndex(teamTotalData[labelId].roleData)
    end
    return {teamTotalData}
end

--- 初始化列表里的节点
function BattleStatisticPopupDialog:InitInfoNodeList()
    local scrollRect = self.RT_ListViewRoot.parent.parent:GetComponent(typeof(ScrollRect))
    if self.questType == Constants.IDType.QuestWorldBoss then
        -- 五人本
        local maxRoleNum = 5
        self:LoopModeFreshInfoNodeList(maxRoleNum)
    elseif AnnihilationUtils.QuestTypeIsAnnihilation(self.questType) then
        -- 歼灭战
        local maxRoleNum = 3
        self:NormalModeInitInfoNodeList(maxRoleNum)
        if not IsNull(scrollRect) then
            scrollRect.enabled = false
        end
    elseif self.questType == Constants.IDType.QuestLadderStruggle
    or self.questType == Constants.IDType.QuestChaoticRecall then
        -- 大乱斗
        local maxRoleNum = 4
        self:NormalModeInitInfoNodeList(maxRoleNum)
        -- 需要打开滚动列表
        if not IsNull(scrollRect) then
            scrollRect.enabled = true
            self.RT_ListViewRoot.anchoredPosition = Vector2.New(0, 0)
        end
    else
        -- 正常模式
        local maxRoleNum = 4
        self:NormalModeInitInfoNodeList(maxRoleNum)
        if not IsNull(scrollRect) then
            scrollRect.enabled = false
        end
    end
end

--- 刷新节点列表到第几个页，第几个标签
---@param teamIndex any
---@param campId any
function BattleStatisticPopupDialog:RefreshInfoNodeList(pageId, lableId)
    local teamTotalInfo = self.teamStatisticInfo[pageId]
    if isNull(teamTotalInfo) then return end
    local playerTeamTotalInfo = teamTotalInfo[lableId]
    -- if isNull(playerTeamTotalInfo) then return end
    if self.questType == Constants.IDType.QuestWorldBoss then
        -- 五人本（循环列表的刷新模式）
        if isNull(playerTeamTotalInfo) then return end
        self.curPlayerTeamStatisticInfo = playerTeamTotalInfo
        local maxRoleNum = 5
        self:LoopModeFreshInfoNodeList(maxRoleNum)
    else
        -- 其他模式（非循环列表，直接更新节点信息）
        local showRoleNum = isNull(playerTeamTotalInfo) and 0 or #playerTeamTotalInfo.roleData
        for i, infoNodeGO in ipairs(self.infoNodeList) do
            if i <= showRoleNum then
                local LB_infoNode = GetLuaBehaviour(infoNodeGO, BattleStatisticCharacterNode)
                if LB_infoNode then
                    LB_infoNode:Init()
                    local LT_infoNode = LB_infoNode.Env
                    local roleData = playerTeamTotalInfo.roleData[i]
                    local cardDojo = UIBattlingTools:GetCardInfo(roleData.index, roleData.playerCardId, self.teamId)
                    cardDojo.playerCardId = roleData.playerCardId
                    LT_infoNode:SetCharacterInfo(cardDojo)
                    LT_infoNode:SetCharacterBattleInfo(roleData, playerTeamTotalInfo)
                    KTool.SetActive(infoNodeGO, true)
                end
            else
                KTool.SetActive(infoNodeGO, false)
            end
        end
        for i, nullNodeGO in pairs(self.nullNodeList) do
            KTool.SetActive(nullNodeGO, i > showRoleNum)
        end
    end
end

--- 普通列表模式初始化节点数组
---@param maxRoleNum integer @ 最大出战人数
function BattleStatisticPopupDialog:NormalModeInitInfoNodeList(maxRoleNum)
    KTool.SetActive(self.LoopListView, false)

    local infoCell = self.InfoCell.gameObject
    local nullCell = self.NullCell.gameObject
    for i = 1, maxRoleNum, 1 do
        local goInfo = GameObject.Instantiate(infoCell, self.RT_ListViewRoot)
        table.insert(self.infoNodeList, goInfo)
    end
    for i = 1, maxRoleNum, 1 do
        local goNull = GameObject.Instantiate(nullCell.gameObject, self.RT_ListViewRoot)
        table.insert(self.nullNodeList, goNull)
    end
end

---刷新角色伤害列表
function BattleStatisticPopupDialog:LoopModeFreshInfoNodeList(maxRoleNum)
    KTool.SetActive(self.RT_ListViewRoot, false)

    if not self.LoopListView.IsListViewInit then
        self.LoopListView:InitListView(maxRoleNum, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.LoopListView, maxRoleNum)
    end
end

function BattleStatisticPopupDialog:OnGetItemByIndex(loopListView, index)
    if index < 0 then
        return nil
    end

    local cell
    local campTotalInfo = self.curPlayerTeamStatisticInfo
    local showRoleNum = #campTotalInfo.roleData
    local luaIndex = index + 1
    if luaIndex <= showRoleNum then
        cell = loopListView:NewListViewItem("InfoCell")
        local LB_infoNode = GetLuaBehaviour(cell.gameObject, BattleStatisticCharacterNode)
        if not cell.IsInitHandlerCalled then
            cell.IsInitHandlerCalled = true
            LB_infoNode:Init()
        end
        if not KTool.IsNull(LB_infoNode) then
            local roleData = campTotalInfo.roleData[luaIndex]
            local cardInfo = UIBattlingTools:GetCardInfo(roleData.index, roleData.playerCardId, self.teamId)
            local LT_infoNode = LB_infoNode.Env
            LT_infoNode:SetCharacterInfo(cardInfo)
            LT_infoNode:SetCharacterBattleInfo(roleData, campTotalInfo)
        end
    else
        cell = loopListView:NewListViewItem("NullCell")
    end    

    return cell
end

