function BattleStatisticPopupDialog:InitTabToggle(pageId, labelNums, labelStrings)
    local env = CfUtils.GetLuaScr(self.RT_TabToggleGroup.gameObject, "Game.Behaviours.CommonTabToggleUp")
    if isNull(env) then
        return
    end

    local data = {}
    for i = 1, labelNums, 1 do
        local labelData = {
            text = localize("队伍_num_", {_num_ = i}),
            showNormalBg = true,
            func = function()
                self:RefreshInfoNodeList(pageId, i)
                self:SetTotalDamage(pageId, i)
            end
        }
        if not isNull(labelStrings) then
            labelData.text = labelStrings[i]
        end
        table.insert(data, labelData)
    end
    env:FillToggles(data)
end

function BattleStatisticPopupDialog:SetTotalDamage(teamIndex, playerId)
    local teamTotalInfo = self.teamStatisticInfo[teamIndex]
    if isNull(teamTotalInfo) then return end
    local campTotalInfo = teamTotalInfo[playerId]
    if isNull(campTotalInfo) then
        self.TextNumberWorldBoss.text = "0"
        return
    end
    self.TextNumberWorldBoss.text = checkString(campTotalInfo.damage)
end

function BattleStatisticPopupDialog:SortRoleDataByIndex(roleDataList)
    table.sort(roleDataList, function (a,b)
        return a.index < b.index
    end)
end

return BattleStatisticPopupDialog
